/** Complaint statistics — GET /api/v1/complaints/statistics (who may call: holders of complaint.view). */
export function complaintStatistics(query?: { date_from?: string | null; date_to?: string | null }): Promise<ComplaintStatisticsOut> {
  return api<ComplaintStatisticsOut>("GET", withQuery(`/complaints/statistics`, query), undefined);
}

/** The complaints register for a period (PDF) — GET /api/v1/complaints/register/pdf (who may call: holders of complaint.view). */
export function registerPdfComplaints(query: { date_from: string; date_to: string }): Promise<unknown> {
  return api<unknown>("GET", withQuery(`/complaints/register/pdf`, query), undefined);
}

/** The written complaints procedure (PDF) — GET /api/v1/complaints/policy/pdf (who may call: holders of complaint.view or complaint.manage). */
